def _body(robot: dict | None) -> Body:
    if not robot or not robot.get("center"):
        return Body()
    contour = robot.get("contour") or []
    return Body(bool(robot.get("present")), np.array(robot["center"], np.float32),
                np.array(robot.get("vel") or (0.0, 0.0), np.float32), float(robot.get("radius") or 40.0),
                np.array(contour, np.float32) if contour else None, float(robot.get("hp") or 0.0),
                float(robot.get("max_hp") or 0.0), bool(robot.get("outside")))


def snapshot_from(state: dict | None, slot: int, fresh: bool) -> Snapshot:
    if not state:
        return Snapshot("", 0, False, None, None, None, Body(), Body(), "nicht verfügbar", [])
    robots = {r["id"]: r for r in state.get("robots") or []}
    arena = state.get("arena")
    size = (float(arena["size"][0]), float(arena["size"][1])) if arena else None
    bounds = (0.0, 0.0, *size) if size else None
    zone = state.get("zone")
    if zone and size:
        xs, ys = [float(p[0]) for p in zone], [float(p[1]) for p in zone]
        bounds = (min(xs), min(ys), max(xs), max(ys))
    ulti = "nicht verfügbar"
    own = robots.get(slot)
    if own and own.get("ulti"):
        u = own["ulti"]
        ulti = ("verbraucht" if u.get("used") else "bereit" if u.get("ready")
                else f"lädt {round(100 * min(1.0, float(u.get('charge') or 0.0)))} %")
    items = []
    for item in state.get("items") or []:
        center = np.array(item["center"], np.float32)
        poly = np.array(item.get("poly") or [], np.float32)
        radius = float(np.linalg.norm(poly - center, axis=1).mean()) if len(poly) else 30.0
        items.append((item["kind"], center, radius))
    phase = state.get("phase", "")
    fighting = fresh and phase == "fight" and not state.get("finished")
    return Snapshot(phase, int(state.get("battle") or 0), fighting, state.get("elapsed"), size, bounds,
                    _body(own), _body(robots.get(3 - slot)), ulti, items)


def picture(snap: Snapshot, jpeg: bytes | None, frame: dict | None, angle: float | None,
            image_px: int) -> str | None:
    """Arenabild verkleinert und beschriftet, damit das Modell sich und den Gegner sicher erkennt."""
    if not jpeg or not frame or frame.get("kind") != "arena":
        return None
    img = cv2.imdecode(np.frombuffer(jpeg, np.uint8), cv2.IMREAD_COLOR)
    if img is None:
        return None
    w, h, pad = float(frame["w"]), float(frame["h"]), float(frame.get("pad") or 0.0)
    px = image_px / (max(w, h) + 2 * pad)
    img = cv2.resize(img, (max(1, round((w + 2 * pad) * px)), max(1, round((h + 2 * pad) * px))),
                     interpolation=cv2.INTER_AREA)

    def pt(u) -> tuple[int, int]:
        return int((float(u[0]) + pad) * px), int((float(u[1]) + pad) * px)

    cv2.rectangle(img, pt((0, 0)), pt((w, h)), (255, 255, 255), 2)
    if snap.bounds is not None and snap.bounds != (0.0, 0.0, w, h):
        x0, y0, x1, y1 = snap.bounds
        cv2.rectangle(img, pt((x0, y0)), pt((x1, y1)), (0, 140, 255), 2)
    for kind, pos, r in snap.items:
        color = (140, 140, 140) if kind == "obstacle" else (0, 220, 255)
        cv2.circle(img, pt(pos), max(2, int(r * px)), color, 2)
    for body, color, label in ((snap.foe, (40, 40, 230), "GEGNER"), (snap.me, (60, 220, 60), "DU")):
        if not body.present:
            continue
        if body.outline is not None and len(body.outline):
            poly = np.array([pt(p) for p in body.outline], np.int32)
            cv2.polylines(img, [poly], True, color, 2)
        x, y = pt(body.pos)
        org = (x - 20, y - int(body.radius * px) - 6)
        cv2.putText(img, label, org, cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 0), 3)
        cv2.putText(img, label, org, cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 1)
    if snap.me.present and angle is not None:
        tip = snap.me.pos + np.array([math.cos(angle), math.sin(angle)]) * (snap.me.radius + 60)
        cv2.arrowedLine(img, pt(snap.me.pos), pt(tip), (60, 220, 60), 2, tipLength=0.3)
    ok, out = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 80])
    return base64.b64encode(out.tobytes()).decode() if ok else None


# ---------- Roboter ----------

class Bluetooth:
    """Schickt nur Wechsel: die Firmware hält den letzten Befehl, bis ein neuer kommt."""

    def __init__(self, name: str):
        self.name = name
        self.dry_run = not name
        self.client = None
        self.key = STOP
        self._lock = asyncio.Lock()

    @property
    def state(self) -> str:
        if self.dry_run:
            return "Probelauf"
        return "verbunden" if self.client is not None and self.client.is_connected else "getrennt"

    async def connect(self) -> None:
        if self.dry_run:
            log.info("Probelauf: kein Roboter verbunden, Tasten nur in der Konsole.")
            return
        from bleak import BleakClient, BleakScanner

        log.info("Verbinde Roboter „%s“ …", self.name)
        device = await BleakScanner.find_device_by_filter(lambda d, _ad: d.name == self.name, timeout=10)
        if device is None:
            raise PilotError(f"Roboter „{self.name}“ nicht gefunden. Einschalten, näher an diesen PC "
                             "stellen und den KI-Client neu starten.")
        self.client = BleakClient(device)
        await self.client.connect()
        log.info("Roboter „%s“ verbunden.", self.name)

    async def send(self, key: str, force: bool = False) -> None:
        async with self._lock:
            if key == self.key and not force:
                return
            if self.dry_run:
                log.info("Taste %r", key)
            else:
                if self.client is None or not self.client.is_connected:
                    raise PilotError(f"Bluetooth zu „{self.name}“ getrennt. KI-Client neu starten.")
                await self.client.write_gatt_char(CHAR_UUID, key.encode(), response=True)
            self.key = key

    async def close(self) -> None:
        with contextlib.suppress(Exception):
            await self.send(STOP, force=True)
        if self.client is not None:
            with contextlib.suppress(Exception):
                await self.client.disconnect()


class ControllerLink:
    """Leitet Fahrbefehle als UDP-Pakete an den HeboController weiter."""

    def __init__(self, host: str, port: int):
        self.host = host
        self.port = port
        self.key = STOP
        self._seq = 0
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

    @property
    def state(self) -> str:
        return f"Controller {self.host}:{self.port}"

    async def connect(self) -> None:
        return

    async def mode(self, mode: str) -> None:
        self._send({"type": "mode", "mode": mode})

    async def send(self, key: str, force: bool = False) -> None:
        if key == self.key and not force:
            return
        if key == STOP:
            self._send({"type": "stop"})
        else:
            self._send({"type": "drive", "key": key})
        self.key = key

    async def close(self) -> None:
        with contextlib.suppress(Exception):
            await self.send(STOP, force=True)
        with contextlib.suppress(Exception):
            self._sock.close()

    def _send(self, data: dict) -> None:
        self._seq += 1
        packet = {"seq": self._seq, "source": "pilot", "ts_ms": int(time.time() * 1000), **data}
        self._sock.sendto(json.dumps(packet).encode("utf-8"), (self.host, self.port))


class Heading:
    """Front des eigenen Roboters aus der eigenen Bewegung; die Kamera allein kennt sie nicht."""

    def __init__(self):
        self.angle: float | None = None
        self.key = STOP
        self.since = 0.0

    def update(self, key: str, me: Body, t: float) -> None:
        if key != self.key:
            self.key, self.since = key, t
            if key in ("a", "d"):
                # Drehen auf der Stelle macht jede alte Schätzung wertlos.
                self.angle = None
        speed = float(np.linalg.norm(me.vel))
        if key in ("w", "s") and me.present and speed > MOVE_SPEED and t - self.since >= MEASURE_S:
            angle = math.atan2(float(me.vel[1]), float(me.vel[0]))
            self.angle = angle if key == "w" else _wrap(angle + math.pi)

    def held(self, t: float) -> float:
        return t - self.since


def _wrap(a: float) -> float:
    return (a + math.pi) % (2 * math.pi) - math.pi


def _unit(v: np.ndarray) -> np.ndarray:
    n = float(np.linalg.norm(v))
    return v / n if n > 1e-6 else np.array([1.0, 0.0], np.float32)


class Driver:
    """Fährt eine vom Modell gewählte Taktik 20× pro Sekunde; das Modell selbst ist dafür zu langsam."""

    def __init__(self):
        self.tactic = "plan_b"
        self.side = 1
        self._pulse: list[tuple[str, float]] = []

    def set(self, tactic: str, side: int) -> None:
        if tactic in ("auto", "plan_b"):
            tactic = "plan_b"
        self.tactic, self.side = tactic, side

    def _plan_b_mode(self, snap: Snapshot, heading: Heading, center: np.ndarray) -> str:
        me, foe = snap.me, snap.foe
        if not me.present or snap.bounds is None:
            return "hold"
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        near_edge = not (x0 + margin < me.pos[0] < x1 - margin and y0 + margin < me.pos[1] < y1 - margin)
        if near_edge:
            return "edge_safe"
        if not foe.present:
            return "hold"
        gap = float(np.linalg.norm(foe.pos - me.pos)) - me.radius - foe.radius
        if gap < 40.0:
            return "dodge"
        if gap < 150.0:
            if heading.angle is None:
                return "retreat"
            want = math.atan2(float(foe.pos[1] - me.pos[1]), float(foe.pos[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) > math.radians(60):
                return "flank"
            return "attack"
        if gap < 220.0:
            return "flank"
        return "attack"

    def _plan_b_key(self, snap: Snapshot, heading: Heading, t: float) -> str:
        me, foe = snap.me, snap.foe
        if self.tactic == "hold" or not me.present or snap.bounds is None:
            return STOP
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        center = np.array([(x0 + x1) / 2, (y0 + y1) / 2], np.float32)
        mode = self._plan_b_mode(snap, heading, center)
        if mode == "edge_safe":
            outward = _unit(me.pos - center)
            if heading.angle is None:
                return self._start([("s", 0.3)], t)
            front = np.array([math.cos(heading.angle), math.sin(heading.angle)])
            if float(front @ outward) > 0.3:
                return self._start([("s", 0.35)], t)
            target = center
            want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) < ALIGN:
                return "s"
            spin = "d" if diff > 0 else "a"
            return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("s", 0.4)], t)
        if mode == "dodge":
            if not foe.present:
                return STOP
            away = _unit(me.pos - foe.pos)
            target = me.pos + np.array([-away[1], away[0]]) * self.side * 200
            target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
            if heading.angle is None:
                return self._start([("w", 0.25)], t)
            want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) < ALIGN:
                return "w"
            spin = "d" if diff > 0 else "a"
            return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.35)], t)
        if mode == "retreat":
            if not foe.present:
                return STOP
            away = _unit(me.pos - foe.pos)
            target = me.pos + away * 250
            target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
            if heading.angle is None:
                return self._start([("s", 0.4)], t)
            want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) < ALIGN:
                return "s"
            spin = "d" if diff > 0 else "a"
            return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("s", 0.35)], t)
        if mode == "flank":
            if not foe.present:
                return STOP
            away = _unit(me.pos - foe.pos)
            perp = np.array([-away[1], away[0]]) * self.side
            point = foe.pos + perp * (me.radius + foe.radius + 80)
            target = point if float(np.linalg.norm(point - me.pos)) > 90 else foe.pos
            target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
            if heading.angle is None:
                return self._start([("w", 0.25)], t)
            want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) < ALIGN:
                return "w"
            spin = "d" if diff > 0 else "a"
            return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.4)], t)
        if mode == "attack":
            if not foe.present:
                return STOP
            target = foe.pos
            target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
            if heading.angle is None:
                return self._start([("w", 0.25)], t)
            want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
            diff = _wrap(want - heading.angle)
            if abs(diff) < ALIGN:
                return "w"
            spin = "d" if diff > 0 else "a"
            return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.4)], t)
        return STOP

    def key(self, snap: Snapshot, heading: Heading, t: float) -> str:
        while self._pulse and self._pulse[0][1] <= t:
            self._pulse.pop(0)
        if self._pulse:
            return self._pulse[0][0]
        me, foe = snap.me, snap.foe
        if self.tactic in ("auto", "plan_b"):
            return self._plan_b_key(snap, heading, t)
        if self.tactic == "hold" or not me.present or snap.bounds is None:
            return STOP
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        center = np.array([(x0 + x1) / 2, (y0 + y1) / 2], np.float32)
        near_edge = not (x0 + margin < me.pos[0] < x1 - margin and y0 + margin < me.pos[1] < y1 - margin)
        if near_edge:
            # Randschutz geht vor jeder Taktik: eine Kante kostet mehr als ein verpasster Treffer.
            outward = _unit(me.pos - center)
            if heading.angle is not None:
                front = np.array([math.cos(heading.angle), math.sin(heading.angle)])
                if float(front @ outward) > 0.3:
                    return self._start([("s", 0.35)], t)
            target = center
        elif not foe.present and self.tactic != "retreat":
            return STOP
        else:
            target = self._target(snap, center)
        target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
        if heading.angle is None:
            # Steckt der Roboter fest, zeigt Zurückfahren die Front genauso gut.
            if heading.key == "w" and heading.held(t) > STUCK_S:
                return self._start([("s", 0.4)], t)
            return "w" if heading.key not in ("a", "d") else self._start([("w", 0.4)], t)
        want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
        diff = _wrap(want - heading.angle)
        if abs(diff) < ALIGN:
            return "w"
        # Bildkoordinaten: y zeigt nach unten, positiver Winkel ist im Uhrzeigersinn, also rechts.
        spin = "d" if diff > 0 else "a"
        return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.4)], t)

    def _start(self, steps: list[tuple[str, float]], t: float) -> str:
        self._pulse = []
        for key, dur in steps:
            t += dur
            self._pulse.append((key, t))
        return self._pulse[0][0]

    def _target(self, snap: Snapshot, center: np.ndarray) -> np.ndarray:
        me, foe = snap.me, snap.foe
        gap = me.radius + foe.radius
        away = _unit(me.pos - foe.pos)
        if self.tactic == "push_out":
            out = _unit(foe.pos - center)
            # Erst auf die Mittelseite des Gegners, sonst schiebt man ihn zur Mitte statt hinaus.
            if float((me.pos - foe.pos) @ out) > -foe.radius:
                return foe.pos - out * (gap + 60)
            return foe.pos
        if self.tactic == "flank":
            perp = np.array([-away[1], away[0]]) * self.side
            point = foe.pos + perp * (gap + 80)
            return point if float(np.linalg.norm(point - me.pos)) > 90 else foe.pos
        if self.tactic == "circle":
            a = math.radians(40) * self.side
            rot = np.array([away[0] * math.cos(a) - away[1] * math.sin(a),
                            away[0] * math.sin(a) + away[1] * math.cos(a)])
            return foe.pos + rot * CIRCLE_R
        if self.tactic == "retreat":
            return me.pos + away * 250
        if self.tactic == "dodge":
            return me.pos + np.array([-away[1], away[0]]) * self.side * 200
        return foe.pos


# ---------- Modell ----------

class DriveArgs(BaseModel):
    direction: Literal["forward", "back", "left", "right"] = Field(
        description="forward/back fahren, left/right drehen auf der Stelle.")
    ms: int = Field(400, ge=100, le=1500, description="Dauer in Millisekunden, danach Stopp.")


class TacticArgs(BaseModel):
    tactic: Literal["ram", "push_out", "flank", "circle", "retreat", "dodge", "hold", "plan_b"] = Field(
        description="ram: rammen. push_out: von der Mittelseite aus Richtung Rand schieben. flank: seitlich "
                    "angreifen. circle: umkreisen. retreat: Abstand gewinnen. dodge: seitlich ausweichen. "
                    "hold: stehen bleiben. plan_b: automatische Regelsteuerung (Fallback).")
    side: Literal["left", "right"] = Field("right", description="Seite für flank, circle und dodge.")


class SayArgs(BaseModel):
    text: str = Field(description="Kurzer Spruch fürs Publikum, Deutsch, höchstens 80 Zeichen.")


def prompt(slot: int, steering: str) -> str:
    base = (
        f"Du steuerst live einen echten Hebocon-Roboter (Roboter {slot}) in einer Arena. Jede Runde "
        "bekommst du ein Draufsicht-Foto: dein Roboter ist grün umrandet und mit DU beschriftet, der "
        "Gegner rot. Die weiße Linie ist der Arenarand; außerhalb verliert man HP. Orange ist die "
        "schrumpfende erlaubte Zone. Gelbe Kreise heilen, graue Kreise sind Hindernisse und kosten HP. "
        "Ziel: den Gegner rammen und hinausschieben, selbst drinbleiben. Zusammenstöße kosten den "
        "Langsameren HP. Die Ulti (Laser) erst zünden, wenn sie bereit ist. "
        "Handle sofort mit den Werkzeugen und denke nur kurz; jede Sekunde zählt. Antworte danach mit "
        "höchstens einem kurzen Satz zu deinem Plan. Nutze say ab und zu für einen frechen, "
        "familienfreundlichen Spruch fürs Publikum."
    )
    if steering == "taktik":
        return base + (
            " Wähle mit set_tactic eine Taktik; ein schneller Regler fährt sie, bis du eine neue wählst, "
            "und hält dich dabei vom Rand fern. Wechsle nur, wenn die Lage es verlangt."
        )
    return base + (
        " Fahre mit drive. forward ist die Front deines Roboters; die geschätzte Fahrtrichtung steht im "
        "Text und ist im Bild ein grüner Pfeil. Ist sie unbekannt, kurz forward fahren und schauen. "
        "Du darfst in einer Runde mehrere drive-Aufrufe hintereinander machen."
    )


def copilot_client(token: str | None):
    from copilot import CopilotClient

    # None = OpenAI-Schlüssel: dann darf keine GitHub-Anmeldung dieses PCs mitlaufen.
    return CopilotClient(github_token=token or None, use_logged_in_user=token == "", log_level="warning")


def _ensure_runtime(install=None, tries: int = 3) -> None:
    if os.environ.get("COPILOT_CLI_PATH"):
        return
    if install is None:
        from copilot._cli_download import ensure_runtime_wrapper as install
    for attempt in range(1, tries + 1):
        try:
            install()
            return
        except PermissionError as exc:
            # Der Virenscanner hält frisch entpackte Dateien kurz fest und das SDK benennt ohne
            # Wiederholung um; ein zweiter Versuch ein paar Sekunden später klappt in der Regel.
            if attempt == tries:
                raise PilotError(
                    "Copilot konnte nicht eingerichtet werden (Zugriff verweigert). Kurz warten und neu "
                    "starten; hilft das nicht, %LOCALAPPDATA%\\github-copilot-sdk vom Virenscanner "
                    "ausnehmen.") from exc
            log.warning("Copilot-Installation blockiert (%s), neuer Versuch …", exc)
            time.sleep(3)


# ---------- Einrichtung an der Konsole ----------

async def _probe(token: str, client_factory=copilot_client) -> tuple[str, list[dict]]:
    client = None
    try:
        client = client_factory(token)
        await client.start()
        auth = await client.get_auth_status()
        if not auth.isAuthenticated:
            raise PilotError(auth.statusMessage or "Nicht bei GitHub Copilot angemeldet.")
        models = []
        for m in await client.list_models():
            if m.policy is not None and m.policy.state == "disabled":
                continue
            if not m.capabilities.supports.vision:
                continue
            efforts = m.supported_reasoning_efforts or []
            models.append({"id": m.id, "name": m.name,
                           "multiplier": m.billing.multiplier if m.billing else None,
                           "effort": "low" if "low" in efforts else None})
        return auth.login or "", models
    except PilotError:
        raise
    except Exception as exc:
        raise PilotError(f"Copilot nicht erreichbar: {exc}") from exc
    finally:
        if client is not None:
            with contextlib.suppress(Exception):
                await client.stop()


def _openai_models(key: str) -> list[dict]:
    """Prüft den Schlüssel kostenlos über die Modellliste und liefert die passenden Modelle."""
    req = urllib.request.Request(f"{OPENAI_URL}/models", headers={"Authorization": f"Bearer {key}"})
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.load(resp)["data"]
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            raise PilotError("OpenAI lehnt den Schlüssel ab.") from exc
        raise PilotError(f"OpenAI antwortet mit Fehler {exc.code}.") from exc
    except (urllib.error.URLError, TimeoutError) as exc:
        raise PilotError(f"OpenAI nicht erreichbar: {exc}") from exc
    ids = sorted(m["id"] for m in data if OPENAI_MODELS.match(m["id"]) and not OPENAI_SKIP.search(m["id"]))
    return [{"id": i, "name": i, "multiplier": None,
             "effort": "low" if OPENAI_REASONING.match(i) else None} for i in ids]


def _copilot_login() -> tuple[str, list[dict]]:
    token = next((os.environ[k] for k in TOKEN_ENV if os.environ.get(k)), "")
    while True:
        try:
            user, models = asyncio.run(_probe(token))
            break
        except PilotError as exc:
            print(exc)
        print("Entweder auf diesem PC „copilot“ starten und /login ausführen, oder hier ein Token eingeben.")
        token = getpass.getpass("GitHub-Token (github_pat_… oder gho_…; klassische ghp_… gehen nicht, "
                                "leer = abbrechen): ").strip()
        if not token:
            raise PilotError("Ohne Copilot-Anmeldung kann die KI nicht fahren.")
    if not models:
        raise PilotError("Dein Copilot-Zugang bietet kein Modell mit Bildverständnis an.")
    print(f"Bei Copilot angemeldet als {user or 'unbekannt'}.")
    return token, models


def _openai_login() -> tuple[str, list[dict]]:
    key = os.environ.get("OPENAI_API_KEY", "")
    while True:
        if not key:
            key = getpass.getpass("OpenAI-API-Schlüssel (sk-…, von platform.openai.com; leer = abbrechen): "
                                  ).strip()
            if not key:
                raise PilotError("Ohne OpenAI-Schlüssel kann die KI nicht fahren.")
        try:
            models = _openai_models(key)
            break
        except PilotError as exc:
            print(exc)
            key = ""
    if not models:
        raise PilotError("Dein OpenAI-Zugang bietet kein passendes Modell mit Bildverständnis an.")
    print("OpenAI-Schlüssel gilt. Jeder Zug kostet dort Geld (Abrechnung pro Aufruf).")
    return key, models


async def _scan() -> list[str]:
    from bleak import BleakScanner

    devices = await BleakScanner.discover(timeout=5)
    return sorted({d.name for d in devices if d.name and d.name.lower().startswith(ROBOT_PREFIX)})


def _choose(title: str, options: list[str], default: int, *, example: str | None = None) -> int:
    print(title)
    if example:
        print(f"  Beispiel: {example}")
    for i, text in enumerate(options, 1):
        print(f"  {i}) {text}")
    while True:
        text = input(f"Auswahl [{default + 1}]: ").strip()
        if not text:
            return default
        if text.isdigit() and 1 <= int(text) <= len(options):
            return int(text) - 1
        print(f"Bitte eine Zahl von 1 bis {len(options)} eingeben.")


def setup(cfg: dict, forced_controller: str | None = None) -> Setup:
    """Fragt Startmodus und Controller-Endpunkt ab; Plan B fährt ohne LLM-Modell."""
    ai = {**DEFAULTS, **cfg.get("ai", {})}
    mode_default = ai.get("control_mode", "manual")
    default_index = CONTROL_MODES.index(mode_default) if mode_default in CONTROL_MODES else 0
    control_mode = CONTROL_MODES[_choose("Wie startet die Steuerung?", [
        "manuell – externe WASD-Tasten oder Handsteuerung",
        "automatisch – Plan B fährt selbst"], default_index, example=str(default_index + 1))]

    if forced_controller:
        text = forced_controller.strip()
        if ":" in text:
            host_part, port_part = text.rsplit(":", 1)
            if host_part:
                ai["controller_host"] = host_part
            if port_part.isdigit() and 1 <= int(port_part) <= 65535:
                ai["controller_port"] = int(port_part)
        elif text:
            ai["controller_host"] = text

    host_default = str(ai.get("controller_host") or DEFAULTS["controller_host"])
    while True:
        host = input(f"Controller-IP [{host_default}]: ").strip() or host_default
        if host:
            break
        print("Bitte eine IP oder einen Hostnamen eingeben.")

    port_default = int(ai.get("controller_port") or DEFAULTS["controller_port"])
    while True:
        text = input(f"Controller-Port [{port_default}]: ").strip()
        if not text:
            port = port_default
            break
        if text.isdigit() and 1 <= int(text) <= 65535:
            port = int(text)
            break
        print("Bitte einen Port von 1 bis 65535 eingeben.")

    cfg["ai"] = {**ai, "access": "plan_b", "model": "plan_b", "steering": "taktik",
                 "control_mode": control_mode, "robot": "", "controller_host": host,
                 "controller_port": port}
    return Setup("plan_b", "Plan B", None, "taktik", control_mode, "", "",
                 float(ai["turn_s"]), int(ai["max_calls"]), int(ai["image_px"]), "", host, port,
                 float(ai["auto_wait_s"]), float(ai["foe_start_speed"]), int(ai["foe_start_frames"]))


# ---------- Kampf ----------

class Pilot:
    def __init__(self, server: str, token: str, slot: int, cfg: Setup, client_factory=copilot_client):
        self.server = server
        self.token = token
        self.slot = slot
        self.cfg = cfg
        self.client_factory = client_factory
        self.state: dict | None = None
        self.received = 0.0
        self.jpeg: bytes | None = None
        self.frame: dict | None = None
        self.status = ""
        self.error: str | None = None
        self.calls = 0
        self.comment = ""
        self.bt = Bluetooth(cfg.robot)
        self.ctrl = ControllerLink(cfg.controller_host, cfg.controller_port) if cfg.controller_host else None
        self.heading = Heading()
        self.driver = Driver()
        self.control_mode = cfg.control_mode
        self.drive_key = STOP
        self.auto_started = 0.0
        self.auto_ready = False
        self.foe_started = False
        self.foe_frames = 0
        self.patrol_key = STOP
        self.patrol_until = 0.0
        self.wait_notice_left = -1
        self.switch = TerminalSwitch()
        self._terminal_thread = None

    def set_control_mode(self, mode: str) -> None:
        if mode in CONTROL_MODES:
            self.control_mode = mode
            self.cfg.control_mode = mode
            log.info("Steuerung: %s", self.control_mode)

    async def _send_key(self, key: str, force: bool = False) -> None:
        target = self.ctrl or self.bt
        await target.send(key, force=force)
        self.drive_key = target.key

    async def _set_mode(self, mode: str) -> None:
        if mode not in CONTROL_MODES or mode == self.control_mode:
            return
        self.set_control_mode(mode)
        if self.ctrl is not None:
            await self.ctrl.mode(mode)
        # Der Wechsel stoppt bewusst zuerst den alten Dauerbefehl.
        await self._send_key(STOP, force=True)
        self.auto_started = 0.0
        self.auto_ready = False
        self.foe_started = False
        self.foe_frames = 0

    def _update_auto_gate(self, snap: Snapshot, t: float) -> None:
        if self.control_mode != "auto" or not snap.fighting:
            self.auto_started = 0.0
            self.auto_ready = False
            self.foe_started = False
            self.foe_frames = 0
            self.wait_notice_left = -1
            return
        if self.auto_started <= 0.0:
            self.auto_started = t
            self.wait_notice_left = -1
        if not snap.foe.present:
            self.auto_ready = True
            self.wait_notice_left = -1
            return
        speed = float(np.linalg.norm(snap.foe.vel))
        if speed >= self.cfg.foe_start_speed:
            self.foe_frames += 1
        else:
            self.foe_frames = 0
        if self.foe_frames >= self.cfg.foe_start_frames:
            self.foe_started = True
            self.wait_notice_left = -1
        if self.foe_started or (t - self.auto_started) >= self.cfg.auto_wait_s:
            self.auto_ready = True
            self.wait_notice_left = -1

    def _log_wait_countdown(self, t: float) -> None:
        if self.auto_ready or self.auto_started <= 0.0:
            self.wait_notice_left = -1
            return
        left = max(0, math.ceil(self.cfg.auto_wait_s - (t - self.auto_started)))
        if left != self.wait_notice_left:
            self.wait_notice_left = left
            log.info("Auto-Start in %d s (oder sofort, sobald der Gegner fährt).", left)

    def _patrol(self, snap: Snapshot, t: float) -> str:
        me = snap.me
        if not me.present or snap.bounds is None:
            return STOP
        if self.patrol_until > t:
            return self.patrol_key
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        near_edge = not (x0 + margin < me.pos[0] < x1 - margin and y0 + margin < me.pos[1] < y1 - margin)
        close_obstacle = any(
            kind == "obstacle" and float(np.linalg.norm(pos - me.pos)) < me.radius + radius + 80
            for kind, pos, radius in snap.items
        )
        if near_edge:
            key = random.choice(("s", "a", "d"))
            dur = random.uniform(0.2, 0.45)
        elif close_obstacle:
            key = random.choice(("a", "d", "s"))
            dur = random.uniform(0.15, 0.35)
        else:
            key = random.choices(("w", "a", "d", "s", STOP), weights=(6, 2, 2, 2, 1), k=1)[0]
            dur = random.uniform(0.2, 0.6)
        self.patrol_key = key
        self.patrol_until = t + dur
        return key

    async def _handle_terminal_switch(self) -> None:
        while True:
            key = self.switch.pop()
            if key is None:
                return
            if key == "p":
                await self._set_mode("auto" if self.control_mode == "manual" else "manual")

    def _start_terminal_switch(self) -> None:
        if self._terminal_thread is not None and self._terminal_thread.is_alive():
            return
        self._terminal_thread = threading.Thread(target=self.switch.run, name="terminal-switch", daemon=True)
        self._terminal_thread.start()

    def _stop_terminal_switch(self) -> None:
        self.switch.stop()
        if self._terminal_thread is not None:
            self._terminal_thread.join(timeout=1.0)

    def post(self, path: str, data: dict) -> tuple[int, dict]:
        req = urllib.request.Request(f"http://{self.server}{path}", data=json.dumps(data).encode(),
                                     method="POST")
        req.add_header("Content-Type", "application/json")
        req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=3.0) as res:
                return res.status, json.loads(res.read())
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, json.loads(exc.read())
            except ValueError:
                return exc.code, {"ok": False, "message": f"Server antwortet mit Fehler {exc.code}."}

    def _status(self, text: str) -> None:
        if text != self.status:
            log.info(text)
            self.status = text

    def public(self) -> dict:
        return {"status": self.status, "model": self.cfg.label, "steering": self.cfg.steering,
                "control_mode": self.control_mode,
                "robot": self.cfg.robot or ("Controller" if self.ctrl else "Probelauf"),
                "bluetooth": (self.ctrl.state if self.ctrl else self.bt.state),
                "max_calls": self.cfg.max_calls,
                "tactic": self.driver.tactic if self.cfg.steering == "taktik" else None,
                "key": self.drive_key.strip() or None, "comment": self.comment, "error": self.error,
                "calls": self.calls}

    def snapshot(self) -> Snapshot:
        return snapshot_from(self.state, self.slot, time.monotonic() - self.received < STALE_S)

    async def main(self) -> None:
        client = None
        tasks: list[asyncio.Task] = []
        try:
            self._start_terminal_switch()
            if self.ctrl is not None:
                await self.ctrl.connect()
                await self.ctrl.mode(self.control_mode)
                await self._send_key(STOP, force=True)
            else:
                await self.bt.connect()
            self._status("Verbinde KI-Modell …")
            client = self.client_factory(None if self.cfg.api_key else self.cfg.token)
            await client.start()
            tasks = [asyncio.create_task(c) for c in (self._read(), self._watch(), self._think(client),
                                                      self._report())]
            done, _ = await asyncio.wait(tasks, return_when=asyncio.FIRST_EXCEPTION)
            for task in done:
                task.result()
        finally:
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            self._stop_terminal_switch()
            if self.ctrl is not None:
                await self.ctrl.close()
            else:
                await self.bt.close()
            if client is not None:
                with contextlib.suppress(Exception):
                    await client.stop()

    async def _read(self) -> None:
        from websockets.asyncio.client import connect
        from websockets.exceptions import ConnectionClosed, WebSocketException

        url = f"ws://{self.server}/ws?" + urllib.parse.urlencode({"token": self.token, "frames": 1})
        lost = False
        while True:
            try:
                async with connect(url, max_size=None, open_timeout=5) as ws:
                    if lost:
                        log.info("Verbindung zum Server wieder da.")
                        lost = False
                    async for packet in ws:
                        self._take(packet)
            except ConnectionClosed as exc:
                if exc.rcvd is not None and exc.rcvd.code == 4401:
                    raise PilotError("Der Server kennt diese Anmeldung nicht mehr. KI-Client neu starten.") \
                        from exc
            except (OSError, TimeoutError, WebSocketException):
                pass
            if not lost:
                log.warning("Verbindung zum Server %s verloren, versuche weiter …", self.server)
                lost = True
            await asyncio.sleep(1.0)

    def _take(self, packet: bytes) -> None:
        n = int.from_bytes(packet[:4], "little")
        state = json.loads(packet[4:4 + n])
        jpeg = packet[4 + n:]
        if jpeg and state.get("frame"):
            self.jpeg, self.frame = jpeg, state["frame"]
        self.state, self.received = state, time.monotonic()

    async def _watch(self) -> None:
        """Schnelle Schleife: Fahrtrichtung schätzen, Taktik fahren und außerhalb des Kampfs anhalten."""
        battle = None
        while True:
            while True:
                key = self.switch.pop()
                if key is None:
                    break
                if key == "p":
                    await self._set_mode("auto" if self.control_mode == "manual" else "manual")
            snap = self.snapshot()
            t = time.monotonic()
            self._update_auto_gate(snap, t)
            self.heading.update(self.drive_key, snap.me, t)
            if snap.battle != battle:
                battle = snap.battle
                self.driver.set("hold", 1)
                self.auto_started = 0.0
                self.auto_ready = False
                self.foe_started = False
                self.foe_frames = 0
            if self.control_mode == "manual":
                # Manuelle Tasten bleiben der äußeren Steuerung vorbehalten; der Auto-Driver darf hier
                # nicht die Richtung überschreiben und damit den Menschen ausstecken.
                pass
            elif not snap.fighting:
                await self._send_key(STOP)
            elif not self.auto_ready:
                self._log_wait_countdown(t)
                await self._send_key(STOP)
            elif snap.foe.present and not self.foe_started:
                # Solange der Gegner noch steht, patrouilliert die KI nur und vermeidet voreilige Angriffe.
                await self._send_key(self._patrol(snap, t))
            elif self.cfg.steering == "taktik":
                await self._send_key(self.driver.key(snap, self.heading, t))
            await asyncio.sleep(WATCH_S)

    async def _report(self) -> None:
        while True:
            try:
                code, _ = await asyncio.to_thread(self.post, "/api/ai_status", {"status": self.public()})
            except (OSError, ValueError):
                code = 0
            if code in (401, 403):
                raise PilotError("Die Moderation hat die KI vom Platz genommen. Zum Weiterspielen den "
                                 "KI-Client neu starten.")
            await asyncio.sleep(STATUS_S)

    async def _think(self, client) -> None:
        session = None
        battle = None
        turns = 0
        try:
            while True:
                snap = self.snapshot()
                if not snap.fighting:
                    self._status("Bereit, wartet auf den Kampf")
                    await asyncio.sleep(0.2)
                    continue
                if snap.battle != battle:
                    battle, self.calls = snap.battle, 0
                    session = await self._drop(session)
                if self.calls >= self.cfg.max_calls:
                    self._status("Anfragelimit für diesen Kampf erreicht")
                    self.driver.set("hold", 1)
                    await asyncio.sleep(0.5)
                    continue
                if session is None or turns >= SESSION_TURNS:
                    await self._drop(session)
                    session = await self._session(client)
                    turns = 0
                self._status("Kämpft")
                started = time.monotonic()
                image = picture(snap, self.jpeg, self.frame, self.heading.angle, self.cfg.image_px)
                attachments = [{"type": "blob", "data": image, "mimeType": "image/jpeg"}] if image else None
                self.calls += 1
                turns += 1
                try:
                    reply = await session.send_and_wait(self.describe(snap), attachments=attachments,
                                                        timeout=TURN_TIMEOUT_S)
                except TimeoutError:
                    log.warning("Modell antwortet nicht rechtzeitig.")
                    with contextlib.suppress(Exception):
                        await session.abort()
                    continue
                except Exception as exc:
                    # Netz- oder Modellfehler: mit frischer Sitzung weiter statt den ganzen Kampf aufzugeben.
                    self.error = f"Modell: {exc}"[:120]
                    log.warning(self.error)
                    session = await self._drop(session)
                    await asyncio.sleep(2.0)
                    continue
                self.error = None
                text = getattr(getattr(reply, "data", None), "content", None) or ""
                if text.strip():
                    self.comment = text.strip()[:200]
                    log.info("Runde %d: %s", self.calls, self.comment)
                await asyncio.sleep(max(0.0, self.cfg.turn_s - (time.monotonic() - started)))
        finally:
            await self._drop(session)

    @staticmethod
    async def _drop(session) -> None:
        if session is not None:
            with contextlib.suppress(Exception):
                await session.disconnect()

    async def _session(self, client):
        from copilot import PermissionHandler, ToolSet

        extra = {"reasoning_effort": self.cfg.effort} if self.cfg.effort else {}
        if self.cfg.api_key:
            extra["provider"] = {"type": "openai", "base_url": OPENAI_URL, "api_key": self.cfg.api_key}
        return await client.create_session(
            on_permission_request=PermissionHandler.approve_all, model=self.cfg.model, tools=self.tools(),
            system_message={"mode": "replace", "content": prompt(self.slot, self.cfg.steering)},
            # Nur die eigenen Werkzeuge: kein Dateizugriff, keine Shell auf dem KI-PC.
            available_tools=ToolSet().add_custom("*"), skip_custom_instructions=True, streaming=False,
            **extra,
        )

    def tools(self) -> list:
        from copilot import define_tool

        async def drive(args: DriveArgs) -> str:
            if not self.snapshot().fighting:
                return "Gerade läuft kein Kampf; die Motoren bleiben aus."
            key = {"forward": "w", "back": "s", "left": "a", "right": "d"}[args.direction]
            await self._send_key(key)
            end = time.monotonic() + args.ms / 1000
            while time.monotonic() < end and self.snapshot().fighting:
                await asyncio.sleep(WATCH_S)
            await self._send_key(STOP)
            return "Erledigt. " + self.position(self.snapshot())

        async def stop() -> str:
            await self._send_key(STOP)
            return "Angehalten."

        async def set_tactic(args: TacticArgs) -> str:
            self.driver.set(args.tactic, 1 if args.side == "right" else -1)
            log.info("Taktik: %s (%s)", args.tactic, args.side)
            return f"Taktik {args.tactic} aktiv."

        async def ulti() -> str:
            code, result = await asyncio.to_thread(self.post, "/api/ulti", {})
            if code != 200:
                return f"Geht nicht: {result.get('message', code)}"
            log.info("Ulti gezündet.")
            return "Ulti gezündet."

        async def say(args: SayArgs) -> str:
            await asyncio.to_thread(self.post, "/api/say", {"text": args.text})
            log.info("Sagt: %s", args.text)
            return "Gesagt."

        common = [
            define_tool("ulti", description="Laser-Ulti auf den Gegner zünden (nur wenn bereit).",
                        handler=ulti, skip_permission=True),
            define_tool("say", description="Sprechblase über deinem Roboter auf der Bühne.", handler=say,
                        skip_permission=True),
        ]
        if self.cfg.steering == "taktik":
            return [define_tool("set_tactic", description="Taktik wählen, die der Regler fährt. "
                                                          "plan_b: automatische Regelsteuerung (Fallback).",
                                handler=set_tactic, skip_permission=True), *common]
        return [define_tool("drive", description="Kurz fahren oder drehen, danach Stopp.", handler=drive,
                            skip_permission=True),
                define_tool("stop", description="Sofort anhalten.", handler=stop, skip_permission=True),
                *common]

    def position(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        if not me.present:
            return "Dein Roboter ist gerade nicht zu sehen."
        text = f"Du bei ({me.pos[0]:.0f}, {me.pos[1]:.0f})"
        if self.heading.angle is not None:
            text += f", Front zeigt {math.degrees(self.heading.angle) % 360:.0f}°"
        if foe.present:
            dist = float(np.linalg.norm(foe.pos - me.pos)) - me.radius - foe.radius
            text += f"; Gegner bei ({foe.pos[0]:.0f}, {foe.pos[1]:.0f}), Lücke {max(0.0, dist):.0f}"
        return text + "."

    def describe(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        lines = [f"Kampfzeit {snap.elapsed or 0:.0f} s. Koordinaten in Arena-Einheiten, x nach rechts, "
                 "y nach unten; 0° = rechts, 90° = unten."]
        if snap.size is not None:
            lines.append(f"Arena {snap.size[0]:.0f} × {snap.size[1]:.0f}.")
            if snap.bounds is not None and snap.bounds != (0.0, 0.0, *snap.size):
                x0, y0, x1, y1 = snap.bounds
                lines.append(f"Erlaubte Zone x {x0:.0f}–{x1:.0f}, y {y0:.0f}–{y1:.0f}.")
        lines.append(f"Du: {me.hp:.0f}/{me.max_hp:.0f} HP{', AUSSERHALB!' if me.outside else ''}. "
                     f"Gegner: {foe.hp:.0f}/{foe.max_hp:.0f} HP{', außerhalb' if foe.outside else ''}.")
        unknown = " Fahrtrichtung unbekannt." if self.heading.angle is None else ""
        lines.append(self.position(snap) + unknown)
        lines.append(f"Ulti: {snap.ulti}.")
        if self.cfg.steering == "taktik":
            lines.append(f"Aktuelle Taktik: {self.driver.tactic}.")
        for kind, pos, _r in snap.items:
            label = "Hindernis" if kind == "obstacle" else "Power-up"
            lines.append(f"{label} bei ({pos[0]:.0f}, {pos[1]:.0f}).")
        return "\n".join(lines)


def run(server: str, result: dict, cfg: Setup) -> None:
    """Kämpft, bis Strg+C, Rauswurf oder ein Fehler kommt; danach steht der Roboter."""
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s", datefmt="%H:%M:%S")
    for noisy in ("websockets", "bleak", "copilot"):
        logging.getLogger(noisy).setLevel(logging.WARNING)
    pilot = Pilot(server, result["token"], result["slot"], cfg)
    robot_label = (cfg.robot or
                   (f"Controller {cfg.controller_host}:{cfg.controller_port}" if cfg.controller_host
                    else "Probelauf"))
    log.info("KI %s steuert Roboter %d (%s, %s). Beenden mit Strg+C.", cfg.label, result["slot"],
             robot_label, cfg.steering)
    asyncio.run(pilot.main())
